	private static void AddConfigDescriptions()
	{
		Add("Treat OmegaM/OmegaF as immune if you have their corresponding Packet Filter status (also applies to Normal).", "해당 패킷 필터 상태가 있으면 오메가M/오메가F를 면역으로 취급(일반 난이도에도 적용).");
